import{_ as i,H as a,f as p,i as n}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"第7章文本编辑工具Vim","description":"","frontmatter":{},"headers":[{"level":2,"title":"7.1 Vim 的 3 种常用模式","slug":"_7-1-vim-的-3-种常用模式","link":"#_7-1-vim-的-3-种常用模式","children":[{"level":3,"title":"7.1.1 一般模式","slug":"_7-1-1-一般模式","link":"#_7-1-1-一般模式","children":[]},{"level":3,"title":"7.1.2 编辑模式","slug":"_7-1-2-编辑模式","link":"#_7-1-2-编辑模式","children":[]},{"level":3,"title":"7.1.3 命令模式","slug":"_7-1-3-命令模式","link":"#_7-1-3-命令模式","children":[]}]},{"level":2,"title":"7.2 Vim 实践","slug":"_7-2-vim-实践","link":"#_7-2-vim-实践","children":[]},{"level":2,"title":"7.3 课后习题","slug":"_7-3-课后习题","link":"#_7-3-课后习题","children":[]}],"relativePath":"跟阿铭学Linux/第7章文本编辑工具Vim.md","filePath":"跟阿铭学Linux/第7章文本编辑工具Vim.md","lastUpdated":1795561067000}'),l={name:"跟阿铭学Linux/第7章文本编辑工具Vim.md"};function t(e,s,h,d,c,o){return a(),p("div",null,[...s[0]||(s[0]=[n(`<h1 id="第7章文本编辑工具vim" tabindex="-1">第7章文本编辑工具Vim <a class="header-anchor" href="#第7章文本编辑工具vim" aria-label="Permalink to &quot;第7章文本编辑工具Vim&quot;">​</a></h1><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前面我们多次提到过vi命令，它是 Linux 中必不可少的工具。早期的 Unix 都是使用 vi 作为系</span></span></code></pre></div><p>统默认的编辑器。也许你会问，vi 与 Vim 有什么区别？其实 Vim 是 vi 的升级版。很多 Linux系统管理员习惯用 vi，因为他们接触 Linux 时用的就是 vi，到后来 Vim 才比较流行。所以无论是用 vi 还是 Vim，只要能达到我们想要的目的即可。</p><p>在阿铭看来，vi 和 Vim 的最大区别就是编辑一个文本时 vi 不会显示颜色，而 Vim 会显示颜色。后者显示颜色更便于用户进行编辑，但其他功能两者并没有太大的区别。所以，在 Linux系统下，使用 vi 还是 Vim 完全取决你的个人喜好。</p><p>如果你的系统里没有 Vim 工具，请按如下方法安装：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># yum install -y vim-enhanced</span></span></code></pre></div><h2 id="_7-1-vim-的-3-种常用模式" tabindex="-1">7.1 Vim 的 3 种常用模式 <a class="header-anchor" href="#_7-1-vim-的-3-种常用模式" aria-label="Permalink to &quot;7.1 Vim 的 3 种常用模式&quot;">​</a></h2><p>Vim 有 3 种模式：一般模式、编辑模式和命令模式，这需要我们牢记。</p><h3 id="_7-1-1-一般模式" tabindex="-1">7.1.1 一般模式 <a class="header-anchor" href="#_7-1-1-一般模式" aria-label="Permalink to &quot;7.1.1 一般模式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当我们使用命令vim filename编辑文件时，会默认进入文件的一般模式。在这个模式下，</span></span></code></pre></div><p>你可以做的操作有：上下移动光标、删除某个字符、删除某行以及复制或粘贴一行或者多行。下面我们先复制一个文件，然后使用 Vim 打开该文件，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># cp /etc/dnsmasq.conf /tmp/1.txt</span><span> // 因为该文件行比较多，适合我们做试验</span></span>
<span class="line"><span># vim /tmp/1.txt</span></span></code></pre></div><p>首先复制一个文件到 /tmp/ 目录下，并改名为 1.txt。然后使用 Vim 工具编辑它，按回车后进入文件 1.txt，该模式就是一般模式。在该模式下，我们可以移动光标的位置，操作方法如表7-1 所示。</p><p>表 7-1 移动光标</p><p>按键</p><ul><li>作用</li></ul><p>h 或者向左的方向键</p><ul><li>光标向左移动一个字符</li></ul><p>l（小写字母 l）或者向右的方向键</p><ul><li>光标向右移动一个字符</li></ul><p>k 或者向上的方向键</p><ul><li>光标向上移动一个字符</li></ul><p>j 或者向下的方向键</p><ul><li>光标向下移动一个字符</li></ul><p>Ctrl+B</p><ul><li>文本页面向前翻一页</li></ul><p>Ctrl+F</p><ul><li>文本页面向后翻一页</li></ul><p>数字 0 或者 Shift+6</p><ul><li>移动到本行行首</li></ul><p>Shift+4</p><ul><li>移动到本行行尾</li></ul><p>gg</p><ul><li>移动到首行</li></ul><p>G</p><ul><li>移动到尾行</li></ul><p>nG（n 是任意数字）</p><ul><li>移动到第n行</li></ul><p>在一般模式下，我们还可以实现对字符或字符串的删除、复制、粘贴等操作，如表 7-2 所示。</p><p>表 7-2 删除、复制和粘贴</p><p>按键</p><ul><li>作用</li></ul><p>x 和 X</p><ul><li>x 表示向后删除一个字符，X 表示向前删除一个字符</li></ul><p>nx</p><ul><li>向后删除n个字符</li></ul><p>dd</p><ul><li>删除 / 剪切光标所在的那一行</li></ul><p>ndd（n 为 number 的缩写）</p><ul><li>删除 / 剪切光标所在行之后的n行</li></ul><p>yy</p><ul><li>复制光标所在行</li></ul><p>p</p><ul><li>从光标所在行开始，向下粘贴已经复制或者粘贴的内容</li></ul><p>P</p><ul><li>从光标所在行开始，向上粘贴已经复制或者粘贴的内容</li></ul><p>nyy</p><ul><li>从光标所在行开始，向下复制n行</li></ul><p>u</p><ul><li><p>还原上一步操作</p></li><li><p>按 v 后移动光标会选中指定字符，然后可以实现复制、粘</p></li></ul><p>v</p><ul><li>贴等操作</li></ul><h3 id="_7-1-2-编辑模式" tabindex="-1">7.1.2 编辑模式 <a class="header-anchor" href="#_7-1-2-编辑模式" aria-label="Permalink to &quot;7.1.2 编辑模式&quot;">​</a></h3><p>在一般模式下是不可以修改某一个字符的，如果要修改字符，就只能进入编辑模式。从一般模式进入编辑模式，只需按 i、I、a、A、o、O、r 和 R 中的某一个键即可。当进入编辑模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时，在屏幕的尾行会显示INSERT或REPLACE的字样（如果你的 CentOS 支持中文，则会显示</span></span></code></pre></div><p>“插入”）。从编辑模式回到一般模式，只需按 Esc 键即可。具体行为对照表如表 7-3 所示。</p><p>表 7-3 进入编辑模式</p><p>按键</p><ul><li>作用</li></ul><p>i</p><ul><li>在当前字符前插入</li></ul><p>I</p><ul><li>在光标所在行的行首插入</li></ul><p>a</p><ul><li>在当前字符后插入</li></ul><p>A</p><ul><li>在光标所在行的行尾插入</li></ul><h3 id="_7-1-3-命令模式" tabindex="-1">7.1.3 命令模式 <a class="header-anchor" href="#_7-1-3-命令模式" aria-label="Permalink to &quot;7.1.3 命令模式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在一般模式下，输入:或者/即可进入命令模式。在该模式下，我们可以搜索某个字符或者字</span></span></code></pre></div><p>符串，也可以实现保存、替换、退出、显示行号等操作，如表 7-4 所示。</p><p>表 7-4 命令模式</p><p>命令</p><ul><li>作用</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/word</span></span>
<span class="line"><span>在光标之后查找一个字符串word，按 n 向后继续搜索</span></span>
<span class="line"><span>?word</span></span>
<span class="line"><span>在光标之前查找一个字符串word，按 n 向前继续搜索</span></span>
<span class="line"><span>在 n1 和 n2 行之间查找word1并替换为word2，不加 g</span></span>
<span class="line"><span>:n1,n2s/word1/word2/g</span></span>
<span class="line"><span>则只替换每行的第一个word1</span></span>
<span class="line"><span>将文档中所有的word1都替换为word2，不加 g 则只替换</span></span>
<span class="line"><span>:1,$s/word1/word2/g</span></span>
<span class="line"><span>每行的第一个word1</span></span></code></pre></div><p>命令模式的其他功能，如表 7-5 表示。</p><p>表 7-5 命令模式的其他功能</p><p>命令</p><ul><li>作用</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:w</span></span></code></pre></div><ul><li>保存文本</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:q</span></span></code></pre></div><ul><li>退出 Vim</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:w!</span></span></code></pre></div><ul><li>强制保存，在 root 用户下，即使文本只读也可以完成保存</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:q!</span></span></code></pre></div><ul><li>强制退出，所有改动不生效</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:wq</span></span></code></pre></div><ul><li>保存并退出</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:set nu</span></span></code></pre></div><ul><li>显示行号</li></ul><h2 id="_7-2-vim-实践" tabindex="-1">7.2 Vim 实践 <a class="header-anchor" href="#_7-2-vim-实践" aria-label="Permalink to &quot;7.2 Vim 实践&quot;">​</a></h2><p>下面阿铭教你如何在一个空白文档中写入一段文字，然后保存。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">首先输入vim </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">txt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">，直接按回车，进入一般模式，如下所示：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"># vim </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">txt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">然后按 i 键进入编辑模式，在窗口的左下角会显示“</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 插入 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">”或者“</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> INSERT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">”，这说明已</span></span></code></pre></div><p>进入插入模式，允许编辑文档。下面阿铭输入如下文字：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">This </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">is</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a test </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">And</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> this </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">is</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> the </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">first</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> time</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> to</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> using</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;vim&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">It</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;s easy to use &quot;vim&quot;.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">I like to using it, do you like it?</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">编辑后，按 Esc 键，窗口左下角显示的“- 插入 -”或者“- INSERT -”消失，然后输</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">入“:wq”，直接按回车保存刚才输入的文字。如下所示：</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">This is a test file.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">And this is the first time to using &quot;vim&quot;.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">It&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s easy </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">to</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;vim&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">I </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">like</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> to</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> it, do you </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">like</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> it?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">~</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">~</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:wq</span></span></code></pre></div><p>此时我们可以查看 test.txt 文档的内容，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># cat test.txt</span></span>
<span class="line"><span>This is a test file.</span></span>
<span class="line"><span>And this is the first time to using &quot;vim&quot;.</span></span>
<span class="line"><span>It&#39;s easy to use &quot;vim&quot;.</span></span>
<span class="line"><span>I like to using it, do you like it?</span></span></code></pre></div><p>Vim 为全键盘操作的编辑器，在各模式下都有很多功能键。阿铭在前面几个表中列出来的都是最常用的功能，你要多加练习，其他不常用的功能也需要了解一下。如果你能全部掌握阿铭列出来的功能，那么基本上算是掌握了 Vim。下面阿铭带着大家一起来练习一下。首先，复制一个示例文本文档，如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># cp /etc/dnsmasq.conf /tmp/1.txt</span><span> // 再次复制该文件</span></span>
<span class="line"><span># vim /tmp/1.txt</span></span></code></pre></div><p>请完成如下操作。</p><p>(1) 分别向下、向右、向左、向上移动 6 个字符（6j 6l 6h 6k）。</p><p>(2) 分别向下、向上翻两页（分别按两次 Ctrl+F 和 Ctrl+B）。</p><p>(3) 把光标移动到第 49 行（49G）。</p><p>(4) 把光标移动到行尾，再移动到行首（Shift+4，Shift+6）。</p><p>(5) 移动到 1.txt 文件的最后一行（G）。</p><p>(6) 移动到文件的首行（gg）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(7) 搜索文件中出现的dnsmasq字符串，并数一下该字符串出现的次数（输入/dnsmsq，然后</span></span></code></pre></div><p>按 n）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(8) 把从第 1 行到第 10 行出现的 dnsmasq 都替换成 dns（:1,10s/dnsmasq/dns/g）。</span></span></code></pre></div><p>(9) 还原上一步操作（u）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(10) 把整个文件中所有的 etc 替换成 cte（:1,$s/etc/cte/g）。</span></span>
<span class="line"><span>(11) 把光标移动到第 25 行，删除字符串anchors（输入 25G 后回车，然后按 j 向右移动光</span></span></code></pre></div><p>标找到 anchors，按 v 选中，然后按 x）。</p><p>(12) 还原上一步操作（u）。</p><p>(13) 删除第 50 行（50G dd）。</p><p>(14) 还原上一步操作（u）。</p><p>(15) 删除第 37 行至第 42 行的所有内容（37G 6dd）。</p><p>(16) 还原上一步操作（u）。</p><p>(17) 复制第 48 行的内容并将其粘贴到第 52 行下面（48G yy 52G p）。</p><p>(18) 还原上一步操作（按两下 u）。</p><p>(19) 复制第 37 行至第 42 行的内容并将其粘贴到第 44 行上面（37G 6yy 44G P）。</p><p>(20) 还原上一步操作（按两下 u）。</p><p>(21) 把第 37 行至第 42 行的内容移动到第 19 行下面（37G 6dd 19G p）。</p><p>(22) 还原上一步操作（按两下 u）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(23) 把光标移动到首行，把第 1 行内容改为#!/bin/bash（先按 gg 把光标定位到第 1 行，</span></span></code></pre></div><p>然后按字母 A，进入编辑模式，同时将光标移到行末尾进行修改操作，完成后按 Esc 键）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(24) 在第 1 行下面插入新的一行，并输入# Hello!（先按 gg 将光标定位到第 1 行，然后按</span></span>
<span class="line"><span>o 进入编辑模式，同时将光标下移另起一行，输入# Hello!）。</span></span>
<span class="line"><span>(25) 保存文档并退出（按 Esc 键，输入:wq）。</span></span></code></pre></div><h2 id="_7-3-课后习题" tabindex="-1">7.3 课后习题 <a class="header-anchor" href="#_7-3-课后习题" aria-label="Permalink to &quot;7.3 课后习题&quot;">​</a></h2><p>(1) vi 与 Vim 有什么区别？它们之间有什么关系？</p><p>(2) 如何查看当前系统的 Vim 版本？</p><p>(3) 如何把文档中出现的 abc 全部替换成 def？如何只替换每行中出现的第一个 abc？</p><p>(4) 当搜索某个关键词时，光标定位的关键词所在的行是如何决定的？也就是说，光标是定位到出现关键词的最顶端那行还是最底端那行，还是另外的情况？如何从当前关键词移动到下一个关键词？如何从当前关键词移动到上一个关键词呢？</p><p>(5) 当编辑完文档后，按 Esc 键进入命令模式，此时输入命令:x，会怎么样？</p><p>(6) 在一般模式下，如何把光标快速向右或向左移动 10 个字符？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(7) vim + filename表示什么含义？执行vim +10 filename将会发生什么？</span></span></code></pre></div><p>(8) 用 Vim 打开文档后，如何使光标跳转到第 20 行？如何使光标跳到最后一行呢？</p><p>(9) 用 Vim 打开文档后，默认是不显示行号的，如何才能显示行号呢？</p><p>(10) 用 Vim 打开文档后，如何把第 20 行至第 50 行中的第一个 abc 替换为 efg？如果想替换所有的 abc 呢？</p><p>(11) 用 Vim 打开文档后，如何快速删除前 100 行？</p><p>(12) 用 Vim 打开文档后，如何复制一行并将其粘贴到第 20 行的下面？</p>`,149)])])}const g=i(l,[["render",t]]);export{u as __pageData,g as default};
